Definition sci_segA1_post (sp gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (q w lo shi : Z) (j7 : list byte) (ra s0 s1 s2 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' dj,
    ms' = MS (mkR (Z_to_bv 64 ASCI_DEL1_RET) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                  (Z_to_bv 64 (q + 24)) (Z_to_bv 64 (q + 32)) (Z_to_bv 64 (bv_unsigned sp + -72)) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 (Z.shiftr (q + 24) 3 + 2147450880)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_VEC_STATEP_DESTROY) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (q + 8, q + 12)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -80)
    /\ rw_cells asegs m' (bv_unsigned sp + -80) [CB 8 dj; C8 (Z_to_bv 64 (q + 72)); C8 (Z_to_bv 64 (Z.shiftr q 3 + 2147450880)); C8 (Z_to_bv 64 2147450880);
