    /\ rw_cells asegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells asegs m' q (SpcHdrCells (mkSPC AVP_SPCI_IMPL 0 w 1) j7)
