  ro_cells asegs m PC [C8 (wz q)] -> aapp PC 8 -> PC mod 8 = 0 -> accessible m PC 8 ->
  rw_cells asegs m q (SpcHdrCells (mkSPC AVP_SPCI_IMPL 1 w 1) j7) -> 0 <= w < 2^31 ->
  aapp q SZ_SPCI_IMPL -> q mod 16 = 0 -> addressable m q SZ_SPCI_IMPL -> (PC + 8 <= q \/ q + SZ_SPCI_IMPL <= PC) ->
  AXStatics2 m ->
  stk asegs m lo (bv_unsigned sp) -> lo + 80 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  evt asegs (sci_segA1_post sp gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q w lo shi j7 ra s0 s1 s2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 PC) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
