(* [comment removed for export] *)
Definition sci_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (q u lk lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 q) (Z_to_bv 64 96) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPDEL2) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (q, q + 32)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' q (SpcHdrCells (mkSPC AVP_SPCI_IMPL u 0 0) j7)
    /\ APMutex m' (q + 32) lk
    /\ ACONST m'.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

Lemma sci_segB : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (q u lk lo : Z) (j7 dj : list byte),
  (pcv = Z_to_bv 64 ASCI_DEL1_RET \/ pcv = ret_pc (Z_to_bv 64 ASCI_DEL1_RET)) ->
  rw_cells asegs m (bv_unsigned sp + -80) [CB 8 dj; C8 (Z_to_bv 64 (q + 72)); C8 (Z_to_bv 64 (Z.shiftr q 3 + 2147450880)); C8 (Z_to_bv 64 2147450880);
                                           C8 (Z_to_bv 64 q); C8 (Z_to_bv 64 ASCI_REL_RET)] ->
  rw_cells asegs m (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells asegs m q (SpcHdrCells (mkSPC AVP_SPCI_IMPL u 1 1) j7) -> 0 <= u < 2^31 ->
  APMutex m (q + 32) lk ->
  aapp q SZ_SPCI_IMPL -> q mod 16 = 0 -> addressable m q SZ_SPCI_IMPL ->
  AXStatics2 m ->
  stk asegs m lo (bv_unsigned sp + -80) -> lo + 96 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m -> ACONST m ->
  evt asegs (sci_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q u lk lo j7 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (Z_to_bv 64 (q + 24)) (Z_to_bv 64 (q + 32))
             a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (Z.shiftr (q + 24) 3 + 2147450880)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
